  if (v.name !== undefined) o['name'] = v.name
  if (v.privateNetworks !== undefined)
    o['private-networks'] = v.privateNetworks.map((x) => toWireInstancePrivateNetworks(x))
  if (v.publicIP !== undefined) o['public-ip'] = v.publicIP
  if (v.publicIPAssignment !== undefined) o['public-ip-assignment'] = v.publicIPAssignment
  if (v.securebootEnabled !== undefined) o['secureboot-enabled'] = v.securebootEnabled
  if (v.securityGroups !== undefined)
    o['security-groups'] = v.securityGroups.map((x) => toWireSecurityGroupRef(x))
  if (v.snapshots !== undefined) o['snapshots'] = v.snapshots.map((x) => toWireSnapshotRef(x))
  if (v.sshKey !== undefined) o['ssh-key'] = toWireSSHKey(v.sshKey)
  if (v.sshKeys !== undefined) o['ssh-keys'] = v.sshKeys.map((x) => toWireSSHKey(x))
  if (v.state !== undefined) o['state'] = v.state
  if (v.template !== undefined) o['template'] = toWireTemplate(v.template)
  if (v.tpmEnabled !== undefined) o['tpm-enabled'] = v.tpmEnabled
  if (v.userData !== undefined) o['user-data'] = v.userData
  if (v.vpc !== undefined) o['vpc'] = toWireInstanceVpc(v.vpc)
  return o
