  /**
   * Template build
   */
  build?: string
  /**
   * Template MD5 checksum
   */
  checksum?: string
  /**
   * Template creation date
   */
  createdAT?: Date
  /**
   * Template default user
   */
  defaultUser?: string
  /**
   * Template description
   */
