/**
 * Hierarchical breakdown of impact in a given zone
 */
export interface ZoneImpact {
  impact: Record<string, ImpactValueWithUnit>
  resources: Record<string, ImpactResourceTreeNode>
}

/** @internal */
export function toWireZoneImpact(v: ZoneImpact): Record<string, unknown> {
  const o: Record<string, unknown> = {}
  if (v.impact !== undefined)
    o['impact'] = Object.fromEntries(
      Object.entries(v.impact).map(([k, val]) => [k, toWireImpactValueWithUnit(val)]),
    )
  if (v.resources !== undefined)
    o['resources'] = Object.fromEntries(
      Object.entries(v.resources).map(([k, val]) => [k, toWireImpactResourceTreeNode(val)]),
    )
  return o
}

/** @internal */
export function fromWireZoneImpact(w: any): ZoneImpact {
  const v = {} as ZoneImpact
  v.impact = Object.fromEntries(
    Object.entries(w['impact'] ?? {}).map(([k, val]) => [k, fromWireImpactValueWithUnit(val)]),
  )
  v.resources = Object.fromEntries(
    Object.entries(w['resources'] ?? {}).map(([k, val]) => [
      k,
      fromWireImpactResourceTreeNode(val),
    ]),
  )
  return v
}

export type ZoneName =
  | 'ch-dk-2'
  | 'de-muc-1'
  | 'ch-gva-2'
  | 'at-vie-1'
  | 'de-fra-1'
  | 'bg-sof-1'
  | 'at-vie-2'
  | 'hr-zag-1'
